/*
 * Theme tokens are scoped to the row. Day is the default; night applies
 * when an ancestor carries data-theme="night".
 */
.settings-toggle-row {
  --toggle-label: #1f2a24;
  --toggle-hint: #5d6b63;
  --toggle-track-off: #cdd5cf;
  --toggle-track-on: #3f7d5c;
  --toggle-thumb: #ffffff;
  --toggle-focus: #3f7d5c;
  --toggle-divider: rgba(31, 42, 36, 0.08);

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  padding: 0.875rem 0;
  border-bottom: 1px solid var(--toggle-divider);
  color: var(--toggle-label);
}

[data-theme="night"] .settings-toggle-row {
  --toggle-label: #e6ece8;
  --toggle-hint: #94a39b;
  --toggle-track-off: #3a4541;
  --toggle-track-on: #7fb89a;
  --toggle-thumb: #0f1412;
  --toggle-focus: #7fb89a;
  --toggle-divider: rgba(230, 236, 232, 0.08);
}

.settings-toggle-row__text {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
  flex: 1 1 auto;
}

.settings-toggle-row__label {
  font-size: 1rem;
  font-weight: 500;
  line-height: 1.3;
}

.settings-toggle-row__hint {
  font-size: 0.8125rem;
  line-height: 1.3;
  color: var(--toggle-hint);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.settings-toggle-row__switch {
  position: relative;
  flex: 0 0 auto;
  width: 2.75rem;
  height: 1.5rem;
  padding: 0;
  border: none;
  border-radius: 999px;
  background: var(--toggle-track-off);
  cursor: pointer;
  transition: background-color 180ms ease;
}

.settings-toggle-row__switch[data-state="on"] {
  background: var(--toggle-track-on);
}

.settings-toggle-row__switch:focus-visible {
  outline: 2px solid var(--toggle-focus);
  outline-offset: 3px;
}

.settings-toggle-row__thumb {
  position: absolute;
  top: 0.1875rem;
  left: 0.1875rem;
  width: 1.125rem;
  height: 1.125rem;
  border-radius: 50%;
  background: var(--toggle-thumb);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
  transition: transform 180ms ease;
}

.settings-toggle-row__switch[data-state="on"] .settings-toggle-row__thumb {
  transform: translateX(1.25rem);
}

@media (prefers-reduced-motion: reduce) {
  .settings-toggle-row__switch,
  .settings-toggle-row__thumb {
    transition: none;
  }
}
